#!/usr/bin/env python3
"""Tiny herdr socket probe: hprobe.py '<json request>' [read_seconds] [max_lines]"""
import json, os, socket, sys, time

req = sys.argv[1]
secs = float(sys.argv[2]) if len(sys.argv) > 2 else 3.0
max_lines = int(sys.argv[3]) if len(sys.argv) > 3 else 20
sock_path = os.environ.get("HERDR_SOCKET_PATH", os.path.expanduser("~/.config/herdr/herdr.sock"))

s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.connect(sock_path)
s.sendall((req.strip() + "\n").encode())
s.settimeout(secs)
buf = b""
lines = 0
t0 = time.time()
try:
    while lines < max_lines and time.time() - t0 < secs:
        chunk = s.recv(65536)
        if not chunk:
            print("<closed>")
            break
        buf += chunk
        while b"\n" in buf:
            line, buf = buf.split(b"\n", 1)
            lines += 1
            try:
                d = json.loads(line)
            except Exception:
                print("RAW", line[:500]); continue
            # trim large text fields for display
            def trim(o):
                if isinstance(o, dict):
                    return {k: (f"<text {len(v)} bytes, {v.count(chr(10))} nl> " + v[:200].replace("\n", "⏎") if k == "text" and isinstance(v, str) else trim(v)) for k, v in o.items()}
                if isinstance(o, list):
                    return [trim(x) for x in o]
                return o
            print(f"[{time.time()-t0:5.2f}s]", json.dumps(trim(d))[:3000])
except socket.timeout:
    print(f"<timeout after {secs}s, {lines} lines>")
s.close()

