package socket

import (
	"bufio"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

// Client is a persistent connection to the cmux Unix socket.
// It serialises all sends with a mutex so callers can share one instance.
type Client struct {
	socketPath string
	password   string

	mu     sync.Mutex
	conn   net.Conn
	reader *bufio.Reader
}

func NewClient(socketPath, password string) *Client {
	return &Client{socketPath: socketPath, password: password}
}

// Connect establishes (or re-establishes) the connection and authenticates.
func (c *Client) Connect() error {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn != nil {
		c.conn.Close()
		c.conn = nil
		c.reader = nil
	}

	conn, err := net.Dial("unix", c.socketPath)
	if err != nil {
		return fmt.Errorf("connect %s: %w", c.socketPath, err)
	}

	if c.password != "" {
		if err := authenticate(conn, c.password); err != nil {
			conn.Close()
			return fmt.Errorf("auth: %w", err)
		}
	}

	c.conn = conn
	c.reader = bufio.NewReaderSize(conn, 1<<20)
	return nil
}

// Close shuts down the underlying connection.
func (c *Client) Close() {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.conn != nil {
		c.conn.Close()
		c.conn = nil
	}
}

// Send sends a v2 JSON-RPC request and returns the parsed result object.
// If the connection is closed it returns an error; the caller is responsible
// for reconnecting.
func (c *Client) Send(method string, params map[string]any) (json.RawMessage, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn == nil {
		return nil, fmt.Errorf("not connected")
	}

	id := randomHex(8)
	req := map[string]any{
		"id":     id,
		"method": method,
		"params": params,
	}
	if params == nil {
		req["params"] = map[string]any{}
	}

	payload, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal: %w", err)
	}

	_ = c.conn.SetDeadline(time.Now().Add(10 * time.Second))
	if _, err := fmt.Fprintf(c.conn, "%s\n", payload); err != nil {
		c.conn = nil
		c.reader = nil
		return nil, fmt.Errorf("write: %w", err)
	}

	line, err := c.reader.ReadString('\n')
	if err != nil {
		c.conn = nil
		c.reader = nil
		return nil, fmt.Errorf("read: %w", err)
	}
	if len(line) > 8<<20 {
		c.conn = nil
		c.reader = nil
		return nil, fmt.Errorf("response line too large: %d bytes", len(line))
	}
	_ = c.conn.SetDeadline(time.Time{})

	var resp struct {
		OK     bool            `json:"ok"`
		Result json.RawMessage `json:"result"`
		Error  *struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
		return nil, fmt.Errorf("parse response: %w (raw: %q)", err, responseSnippet(line))
	}
	if !resp.OK {
		if resp.Error != nil {
			return nil, fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
		}
		return nil, fmt.Errorf("server returned error")
	}
	return resp.Result, nil
}

// DetectSocketPath returns the best available cmux socket path by reading the
// last-socket-path pointer file written by the cmux Mac app, with fallbacks.
//
// cmux may write the pointer file (and the socket itself) under either the XDG
// state directory (cmux v2+) or the legacy Application Support directory, and
// may name the socket with a uid suffix (cmux-<uid>.sock) or without it
// (cmux.sock). We probe all known locations so a socket that exists under any
// of them is found instead of falling through to the legacy /tmp default.
func DetectSocketPath() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return "/tmp/cmux.sock"
	}
	return detectSocketPath(home, os.Getuid())
}

// detectSocketPath is the pure core of DetectSocketPath, parameterised on home
// and uid so it can be tested against a temporary directory tree. It reads only
// the filesystem (via os.ReadFile/os.Stat) and returns the resolved socket path.
func detectSocketPath(home string, uid int) string {
	appSupport := filepath.Join(home, "Library", "Application Support", "cmux")
	xdgState := filepath.Join(home, ".local", "state", "cmux")

	// Primary: the last-socket-path pointer cmux writes on each launch. It can
	// live in either the XDG state dir or Application Support; prefer a pointer
	// whose socket actually exists, but remember the first non-empty one as a
	// fallback in case none of the referenced sockets stat cleanly.
	var firstPointer string
	for _, pointer := range []string{
		filepath.Join(xdgState, "last-socket-path"),
		filepath.Join(appSupport, "last-socket-path"),
	} {
		data, err := os.ReadFile(pointer)
		if err != nil {
			continue
		}
		p := strings.TrimSpace(string(data))
		if p == "" {
			continue
		}
		if firstPointer == "" {
			firstPointer = p
		}
		if _, err := os.Stat(p); err == nil {
			return p
		}
	}

	// Secondary: probe known socket locations directly, covering both the
	// uid-suffixed and plain socket names in each directory.
	for _, candidate := range []string{
		filepath.Join(xdgState, fmt.Sprintf("cmux-%d.sock", uid)),
		filepath.Join(xdgState, "cmux.sock"),
		filepath.Join(appSupport, "cmux.sock"),
	} {
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
	}

	// A pointer file named a socket that isn't currently present: still prefer
	// it over the hard-coded default (the socket may appear once cmux is ready).
	if firstPointer != "" {
		return firstPointer
	}

	// Legacy fallback
	return "/tmp/cmux.sock"
}

func authenticate(conn net.Conn, password string) error {
	_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
	defer func() { _ = conn.SetDeadline(time.Time{}) }()

	id := randomHex(8)
	req := map[string]any{
		"id":     id,
		"method": "auth.login",
		"params": map[string]any{"password": password},
	}
	payload, _ := json.Marshal(req)
	if _, err := fmt.Fprintf(conn, "%s\n", payload); err != nil {
		return fmt.Errorf("send auth.login: %w", err)
	}

	reader := bufio.NewReader(conn)
	line, err := reader.ReadString('\n')
	if err != nil {
		return fmt.Errorf("read auth response: %w", err)
	}

	var resp struct {
		OK    bool `json:"ok"`
		Error *struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
		return fmt.Errorf("parse auth response: %w (raw: %q)", err, responseSnippet(line))
	}
	if !resp.OK {
		if resp.Error != nil {
			return fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
		}
		return fmt.Errorf("authentication failed")
	}
	return nil
}

func randomHex(n int) string {
	b := make([]byte, n)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// responseSnippet trims and truncates a raw socket line for inclusion in error
// messages, so a non-JSON reply is visible instead of a bare "invalid character
// 'E'". cmux returns plain-text errors for some failures, and a connection that
// has desynced surfaces arbitrary bytes here — both are far easier to diagnose
// with the offending text attached.
func responseSnippet(line string) string {
	s := strings.TrimSpace(line)
	const max = 160
	if len(s) > max {
		return s[:max] + "…"
	}
	return s
}
package poller

import (
	"encoding/json"
	"log"
	"sync"
	"time"

	"github.com/itsmaleen/cmux-companion/bridge/internal/socket"
)

// Notification mirrors the fields we care about from cmux's notification object.
type Notification struct {
	ID          string `json:"id"`
	Title       string `json:"title"`
	Subtitle    string `json:"subtitle"`
	Body        string `json:"body"`
	WorkspaceID string `json:"workspace_id"`
	SurfaceID   string `json:"surface_id"`
	IsRead      bool   `json:"is_read"`
}

// Event is emitted by the poller to subscribers.
// Data is any so that non-notification events (cmux.connected, cmux.disconnected)
// can also be broadcast through the same channel.
type Event struct {
	Type string
	Data any
}

// Poller polls notification.list on an interval and broadcasts new events.
type Poller struct {
	client   *socket.Client
	interval time.Duration

	mu          sync.Mutex
	subscribers []chan Event
	seenIDs     map[string]struct{}
	// Bumped by ResetSeenIDs. A poll captures it before its network call and
	// discards its result if it changed meanwhile, so a notification.list issued
	// before a clear can't repopulate seenIDs with pre-clear IDs afterward.
	generation uint64
}

func New(client *socket.Client, interval time.Duration) *Poller {
	return &Poller{
		client:   client,
		interval: interval,
		seenIDs:  make(map[string]struct{}),
	}
}

// Subscribe returns a buffered channel that receives events.
// Slow consumers drop events rather than blocking the poller.
func (p *Poller) Subscribe() <-chan Event {
	ch := make(chan Event, 32)
	p.mu.Lock()
	p.subscribers = append(p.subscribers, ch)
	p.mu.Unlock()
	return ch
}

// Unsubscribe removes a subscriber. The channel is NOT closed — closing a
// channel that the poller might concurrently be sending to causes a panic.
// The WS handler detects disconnection via other signals (ctx, incoming closed).
func (p *Poller) Unsubscribe(ch <-chan Event) {
	p.mu.Lock()
	defer p.mu.Unlock()
	for i, sub := range p.subscribers {
		if sub == ch {
			p.subscribers = append(p.subscribers[:i], p.subscribers[i+1:]...)
			return
		}
	}
}

// Broadcast sends an event to all current subscribers directly.
// Used to push cmux connection state changes.
func (p *Poller) Broadcast(ev Event) {
	p.mu.Lock()
	subs := make([]chan Event, len(p.subscribers))
	copy(subs, p.subscribers)
	p.mu.Unlock()

	for _, sub := range subs {
		select {
		case sub <- ev:
		default:
			// slow consumer; drop
		}
	}
}

// Run starts the polling loop. It blocks until stop is closed.
func (p *Poller) Run(stop <-chan struct{}) {
	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()

	for {
		select {
		case <-stop:
			return
		case <-ticker.C:
			p.poll()
		}
	}
}

func (p *Poller) poll() {
	// Capture the generation before the network call; if a clear lands while
	// we're waiting on cmux, ingest() will discard this now-stale result.
	p.mu.Lock()
	gen := p.generation
	p.mu.Unlock()

	result, err := p.client.Send("notification.list", nil)
	if err != nil {
		log.Printf("poller: notification.list error: %v", err)
		return
	}

	var payload struct {
		Notifications []Notification `json:"notifications"`
	}
	if err := json.Unmarshal(result, &payload); err != nil {
		log.Printf("poller: parse error: %v", err)
		return
	}

	newOnes, subs := p.ingest(payload.Notifications, gen)
	for _, n := range newOnes {
		ev := Event{Type: "notification.created", Data: n}
		for _, sub := range subs {
			select {
			case sub <- ev:
			default:
				// slow consumer; drop
			}
		}
	}
}

// ingest records unseen notifications and returns the new ones plus a snapshot
// of subscribers to deliver to. If the generation changed since the poll began
// (a notification.clear happened mid-flight), the whole batch is discarded so
// stale IDs don't get re-marked as seen.
func (p *Poller) ingest(notifs []Notification, gen uint64) ([]Notification, []chan Event) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.generation != gen {
		return nil, nil
	}
	var newOnes []Notification
	for _, n := range notifs {
		if _, seen := p.seenIDs[n.ID]; !seen {
			p.seenIDs[n.ID] = struct{}{}
			newOnes = append(newOnes, n)
		}
	}
	subs := make([]chan Event, len(p.subscribers))
	copy(subs, p.subscribers)
	return newOnes, subs
}

// ResetSeenIDs clears the seen-ID set. Called after notification.clear so that
// notifications which reappear after a clear ARE emitted again. Bumping the
// generation also invalidates any notification.list poll already in flight.
func (p *Poller) ResetSeenIDs() {
	p.mu.Lock()
	p.seenIDs = make(map[string]struct{})
	p.generation++
	p.mu.Unlock()
}

