1	// Package herdr is the herdr backend (herdr.dev): a Rust runtime that owns
2	// terminals for coding agents and exposes them over a local socket API. Its
3	// model — workspace → tab → pane, one terminal per pane, per-pane agent
4	// status — is translated onto the phone's cmux-shaped vocabulary here.
5	//
6	// Connection model: every command is one short-lived socket connection (see
7	// client.go). One long-lived connection runs `events.subscribe`; it is the
8	// source of connection state, of the pane cache used to answer reads without
9	// an extra round-trip, and of notifications, which herdr does not keep as a
10	// list — they are synthesised from agent-status transitions to blocked/done.
11	package herdr
12	
13	import (
14		"context"
15		"encoding/json"
