    var info: [String: String] = [:]
    if let sid = n.surfaceID { info["surface_id"] = sid }
    if let wid = n.workspaceID { info["workspace_id"] = wid }
    content.userInfo = info

    let request = UNNotificationRequest(
        identifier: n.id,
        content: content,
        trigger: nil // deliver immediately
    )

