24	// Backend implements backend.Backend over several members.
25	type Backend struct {
26		members []Member
27		hub     *backend.Hub
28	
29		mu sync.Mutex
30		// current is the member that answers commands carrying no id (the phone's
31		// "current workspace" lives in one runtime at a time). It follows
32		// workspace.select and starts as the first connected member.
33		current string
34		// transMu serializes member connection transitions so the aggregate
35		// up/down decision and its broadcast happen in one critical section.
36		transMu sync.Mutex
37	}
38	
39	// New builds a composite of the given members, in priority order.
40	func New(members ...Member) *Backend {
41		return &Backend{members: members, hub: backend.NewHub()}
42	}
43	
44	// Kinds lists the member kinds in order.
45	func (b *Backend) Kinds() []string {
46		out := make([]string, 0, len(b.members))
47		for _, m := range b.members {
48			out = append(out, m.Kind)
49		}
50		return out
51	}
52	
53	func (b *Backend) Info() backend.Info {
54		var caps backend.Capabilities
55		notif := map[string]bool{}
56		for _, m := range b.members {
57			c := m.Backend.Info().Capabilities
58			caps.Browser = caps.Browser || c.Browser
59			caps.AgentStatus = caps.AgentStatus || c.AgentStatus
60			notif[c.Notifications] = true
61		}
62		switch {
63		case len(notif) == 1:
64			for k := range notif {
65				caps.Notifications = k
66			}
67		default:
68			caps.Notifications = "mixed"
69		}
70		return backend.Info{Kind: strings.Join(b.Kinds(), "+"), Capabilities: caps}
71	}
72	
73	func (b *Backend) Hub() *backend.Hub { return b.hub }
74	
75	func (b *Backend) Connected() bool {
76		for _, m := range b.members {
77			if m.Backend.Connected() {
78				return true
79			}
80		}
81		return false
82	}
83	
84	// Ping succeeds when at least one member answers, reporting every failure
85	// otherwise.
86	func (b *Backend) Ping() error {
87		var errs []string
88		for _, m := range b.members {
89			if err := m.Backend.Ping(); err != nil {
90				errs = append(errs, m.Kind+": "+err.Error())
91			} else {
92				return nil
93			}
94		}
95		return fmt.Errorf("%s", strings.Join(errs, "; "))
96	}
97	
98	// Run runs every member and forwards their events into the composite hub,
99	// namespaced. backend.connected is forwarded whenever a member comes up (the
100	// phone refreshes its lists); backend.disconnected only once no member is
101	// left, since the phone treats it as "everything went away".
102	func (b *Backend) Run(ctx context.Context) {
103		var wg sync.WaitGroup
104		for _, m := range b.members {
105			wg.Add(1)
106			go func(m Member) {
107				defer wg.Done()
108				m.Backend.Run(ctx)
109			}(m)
110			wg.Add(1)
111			go func(m Member) {
112				defer wg.Done()
113				b.forward(ctx, m)
114			}(m)
115		}
116		wg.Wait()
117	}
118	
119	func (b *Backend) forward(ctx context.Context, m Member) {
120		events := m.Backend.Hub().Subscribe()
121		defer m.Backend.Hub().Unsubscribe(events)
122		for {
123			select {
124			case <-ctx.Done():
