128			}
129		}
130	}
131	
132	func (b *Backend) forwardEvent(m Member, ev backend.Event) {
133		switch ev.Type {
134		case "backend.connected":
135			b.transMu.Lock()
136			defer b.transMu.Unlock()
137			b.mu.Lock()
138			if b.current == "" {
139				b.current = m.Kind
140			}
141			b.mu.Unlock()
142			b.hub.Broadcast(ev)
143		case "backend.disconnected":
144			b.transMu.Lock()
145			defer b.transMu.Unlock()
146			if !b.Connected() {
147				b.hub.Broadcast(ev)
148				return
149			}
150			// One runtime dropped while another is up: not a bridge-wide outage,
151			// but the phone may be sitting in the dead runtime's workspace. Tell it
